import pptx

pptx_path = "/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/a3fbeb63-0e8c-4a11-bff6-0e3b484c3e9c.pptx"

def extract_all_text(pptx_path):
    prs = pptx.Presentation(pptx_path)
    slides_out = []
    for idx, slide in enumerate(prs.slides, start=1):
        parts = []
        for shape in slide.shapes:
            # visible text
            if hasattr(shape, "text") and shape.text:
                parts.append(shape.text)
            # alt text
            if hasattr(shape, "alternative_text") and shape.alternative_text:
                parts.append(shape.alternative_text)
        # notes
        if hasattr(slide, "has_notes_slide") and slide.has_notes_slide:
            ntf = slide.notes_slide.notes_text_frame
            if ntf and ntf.text:
                parts.append(ntf.text)
        slides_out.append({"slide_number": idx, "text": " \n".join(parts)})
    return slides_out

slide_texts = extract_all_text(pptx_path)
for s in slide_texts:
    print(f"Slide {s['slide_number']}: {s['text']}\n")

